import { sha256 } from '../../core/receipt.da76a6c8d29d.mjs';
export function createMissionComposer({missionId}={}){if(!missionId)throw new Error('missionId is required');let sequence=0;return Object.freeze({submit({text,interrupt=false,attachments=[]}={}){const value=String(text??'').trim();if(!value)throw new Error('text is required');const base={schema:'nolane.ui.mission-guidance.v1',missionId:String(missionId),sequence:++sequence,text:value,attachments:attachments.map(String),delivery:interrupt?'interrupt':'queued'};return Object.freeze({...base,receiptSha256:sha256(JSON.stringify(base))})}})}
